uv5  = tuv*vec2(0.25/tlen,tubes/16.0);
tuv += 0.25*int(8.0 * skym)*(istube == 0.0 ? 1.0 : 0.0);
skym = sat (1+8*mod2.z - 8.0*skym);
noise = near*(istube == 0.0 ? 1.0 : 0.0)* (0.1+texture(sampler_pw_noise_lq,tuv*sc)-texture(sampler_pw_noise_lq,(tuv+0.003)*sc)*0.75).r;
